def git_file(path):
    # The pre-1.8 built-in lists were removed in 38c2eff (1.8 step 4a); read them from the commit before.
    return subprocess.run(["git", "show", f"{OLD_LISTS_AT}:{path}"], cwd=ROOT, capture_output=True, text=True, encoding="utf-8", check=True).stdout


def old_values():
    foods = {}
    src = git_file("src/data/starter-foods.ts")
    for m in re.finditer(r'\{ id: "(B\d{4})", nameUk: "([^"]*)", nameEn: "[^"]*", ([^}]*)\}', src):
        vals = dict((k, float(v)) for k, v in re.findall(r"(\w+): ([\d.]+)", m.group(3)))
        foods[m.group(1)] = {"name": m.group(2), "gi": vals.pop("gi", None), "vals": vals}
    dishes = git_file("src/data/starter-dishes.ts")
    for m in re.finditer(r'\{ id: "(B\d{4})", nameUk: "([^"]*)", nameEn: "[^"]*", rawId: "(B\d{4})", yieldGrams: (\d+) \}', dishes):
        raw = foods[m.group(3)]
        factor = 100 / int(m.group(4))
        foods[m.group(1)] = {"name": m.group(2), "gi": raw["gi"], "vals": {k: v * factor for k, v in raw["vals"].items()}}
    return foods


def main():
    db = json.load(open(os.path.join(ROOT, "src", "data", "verified-foods.json"), encoding="utf-8"))
    old = old_values()
    entries = []
    for e in db["entries"]:
        o = old.get(e["id"])
        change = CHANGES.get(e["id"])
        changed_at = ROUND10_AT if e["id"] in RECIPE_IDS else ROUND9_AT if e["id"] in MOM_IDS else ROUND8_AT if e["id"] in ROUND8_IDS else ROUND7_AT if e["id"] in ROUND7_IDS else ROUND6_AT if e["id"] in ROUND6_IDS else ROUND5_AT if e["id"] in ROUND5_IDS else ROUND_AT
        entries.append({**e, "oldName": o["name"] if o else None, "oldGi": o["gi"] if o else None, "old": o["vals"] if o else None,
                        **({"change": change[0], "reopen": change[1], "changedAt": changed_at} if change else {})})
    data = {"sources": db["sources"], "categories": db["categories"], "entries": entries, "questions": QUESTIONS, "roundAt": ROUND_AT}
    payload = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    html = open(os.path.join(HERE, "review_template.html"), encoding="utf-8").read().replace("__DATA__", payload)
    open(OUT, "w", encoding="utf-8").write(html)
    missing = [e["id"] for e in entries if not e["old"]]
    print("review.html:", len(entries), "entries,", len(html) // 1024, "KB; without old values:", missing)


if __name__ == "__main__":
    main()
